import { execFileSync } from "node:child_process";
import { mkdtempSync, realpathSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { observeModelFamilyActivation } from "../plugins/pipeline-core/lib/model-family-runtime-host.mjs";

const created = mkdtempSync(join(tmpdir(), "al-t2d-probe-"));
const root = realpathSync.native(created);
execFileSync("git", ["init", "-q"], { cwd: root, stdio: "ignore" });
const common = execFileSync("git", ["rev-parse", "--git-common-dir"], { cwd: root, encoding: "utf8" }).trim();
const out = observeModelFamilyActivation({ cwd: root });
console.log(JSON.stringify({ platform: process.platform, ok: out.ok, code: out.code, status: out.status, commonDirRaw: common.length > 0 ? "<nonempty>" : "<empty>" }));
rmSync(created, { recursive: true, force: true });

