import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import * as lib from "../plugins/pipeline-core/lib/dispatch-record.mjs";

const full = (rev) => execFileSync("git", ["rev-parse", rev], { encoding: "utf8" }).trim();
const shaA = full("b8654bf26");
const shaB = full("1097adf62");
const pathA = "plugins/pipeline-core/scripts/goldfish-commit-command-flow.test.mjs";
const pathB = "plugins/pipeline-core/scripts/design-course-session.test.mjs";
const recordPath = "evidence/dispatch-record-ALIGN-T.json";
const record = JSON.parse(readFileSync(recordPath, "utf8"));

const text = [
  "ALIGN-T report. PARTIAL: files A and B are done and committed; file C was NOT started (tool budget checkpoint at 36 of 45 tool uses; the hook demanded hand-back). verify: pending. independent review: pending. PO acceptance: open.",
  "",
  "1. DoD results",
  "A goldfish-commit-command-flow.test.mjs: before 20 tests / 11 pass / 9 fail; after 20 / 10 / 10. Changed: the first test (legacy Goldfish command flow renders separate exact-path argv) pass -> fail, RED by design: the producer still emits the multi-line $CMD form, shown in the failure message. The 9 (c)/(d)/(e) cases are unchanged and still RED.",
  "B design-course-session.test.mjs: before 8 / 6 / 2 (K3C001 and K3C008 failing); after 8 / 6 / 2 (K3C006 and K3C008 failing). K3C001 fail -> pass (separator normalization; no further cause appeared on win32). K3C006 pass -> fail, RED with DESIGN-COURSE-PREPARATION-MUST-BE-IGNORED (production still requires the preparation path to be git-ignored; the fake git now answers check-ignore with exit status 1). K3C008 still RED, also DESIGN-COURSE-PREPARATION-MUST-BE-IGNORED per its artifact. K3C007 unchanged and green.",
  "C design-workflow-package-builder.test.mjs: not started (no before capture, no edit, no commit).",
  "check-consumer-safe-paths.test.mjs DoD check: not run.",
  "",
  "2. Evidence (capture-evidence.mjs, node --test <file>; wrapped exit code 1 each time because RED tests are expected)",
  "evidence/align-t-a-before.txt, evidence/align-t-a-after.txt, evidence/align-t-b-before.txt, evidence/align-t-b-after.txt",
  "",
  "3. Changed files and commits",
  `${shaA} ${pathA}`,
  `${shaB} ${pathB}`,
  "",
  "4. Deliberately not changed",
  "File C and every production or guard file. In K3C006 the outputPrefix evidence/advisor, the initial.json and failure.json artifact files and the exception rationale file stay under root evidence/ (the briefing named only the preparation, readiness and package paths). K3C007 and K3C008 are untouched.",
  "",
  "5. Deviations",
  "(a) In A the no-$ and no-; rule is applied to the structure outside the single-quoted argv words, because the shared fixture body carries a literal $VALUE that is inert inside single quotes; startsWith is used per the briefing wording.",
  "(b) The A before-state was captured by temporarily reverting my own just-made edit and restoring it; net tree effect none.",
  "(c) Briefing-vs-repo: the briefing says K3C008 pins DESIGN-COURSE-BOUND-PATH-IGNORED for an ignored bound path; K3C008 as it exists asserts acceptance of tracked paths and never names that code. Left unchanged as briefed.",
  "(d) Two pairs of independent tool calls were issued in parallel by mistake (briefing: one at a time); no refusal occurred. The advisor tool was not consulted because of the budget.",
  "",
  "6. Open items",
  "File C (R7-3b inversion: DWP2-BUILDER-OUTPUT-IGNORED, drop the temp-ignored assertions, move success fixtures to specs/<feature-id>/evidence/) remains; needs a fresh dispatch or more budget. DoD check-consumer-safe-paths.test.mjs not run. verify: pending. independent review: pending. PO acceptance: open.",
].join("\n");

const resultSha256 = lib.reportSha256(text);
record.effort = "xhigh";
record.candidateCommit = shaB;
record.commits = [shaA, shaB];
record.resultSha256 = resultSha256;
record.log = [
  { phase: "opening: preflight ready, record created and read back", toolUseCount: 4 },
  { phase: "file A: before capture, edit, after capture, commit", toolUseCount: 19 },
  { phase: "file B: before capture, edits, after capture, commit", toolUseCount: 42 },
  { phase: "budget checkpoint: file C not started, record finalized", toolUseCount: 44, note: "Hook demanded hand-back at call 36 of 45." },
];
record.report = { text, changedFiles: [{ path: pathA }, { path: pathB }] };
record.closingAllowance = {
  schema: lib.CLOSING_ALLOWANCE_SCHEMA,
  taskId: "ALIGN-T",
  committed: [shaA, shaB],
  verifiedGreen: [
    { check: "K3C001 after change", file: pathB, result: "passed", artifact: "evidence/align-t-b-after.txt" },
    { check: "K3C007 unchanged", file: pathB, result: "passed", artifact: "evidence/align-t-b-after.txt" },
  ],
  remainsUndone: [
    "File C design-workflow-package-builder.test.mjs not started",
    "DoD check node --test harness/scripts/check-consumer-safe-paths.test.mjs not run",
  ],
  nextBriefingAdjustments: [
    "Brief file C alone; capture its before-state first, then edit",
    "K3C008 does not pin DESIGN-COURSE-BOUND-PATH-IGNORED as the briefing states; decide whether COMMITFLOW-F2 or R7-3B-F2 owns that pin",
    "Budget of 45 is tight for three files with per-file capture, edit, commit and record work",
  ],
};
record.outcome = "committed-partial";

const validators = Object.keys(lib).filter((key) => /^validate.*Record/iu.test(key));
const checks = {};
for (const name of validators) {
  try { checks[name] = JSON.stringify(lib[name](record)).slice(0, 200); } catch (error) { checks[name] = `error ${error.code ?? ""} ${error.message}`; }
}
if (Object.values(checks).some((value) => String(value).startsWith("error"))) {
  console.log(JSON.stringify({ refused: true, checks }));
  process.exit(2);
}
writeFileSync(recordPath, `${JSON.stringify(record, null, 2)}\n`);
console.log(JSON.stringify({ shaA, shaB, resultSha256, validators, checks }));

