import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
const LIB = "<machine-path>";
const lib = (n) => import(pathToFileURL(join(LIB, n)).href);
export async function installAgyFromCentralSnapshot({ sourcePluginRoot, attestationSourceRoot, configRoot, workspaceRoot, deps, runCli, writeInstalledReceipt }) {
  const snap = await lib('agy-central-snapshot.mjs');
  const host = await lib('antigravity-topology-refresh-host.mjs');
  const snapshot = snap.publishAgySnapshot({ sourcePluginRoot, attestationSourceRoot, deps });
  const h = host.createAntigravityRefreshHost({ configRoot, workspaceRoot, approvedSourceRoot: snapshot.root, scope: 'global', globalChangeApproved: true, runCli, writeInstalledReceipt: (r) => writeInstalledReceipt({ ...r, attestationSourceRoot }) });
  const r = h.refresh();
  return { status: r.status, reason: r.reason ?? null, snapshot, refresh: r };
}
export async function applyAgyCentralSnapshotAfterUpdate(o) {
  const p = o.resolveCliPath ? o.resolveCliPath() : null;
  if (p === null) return { status: 'skipped', reason: 'AGS-AGY-CLI-ABSENT', snapshot: null };
  return installAgyFromCentralSnapshot(o);
}
export async function observeAgyStartHint({ workspaceRoot, configRoot, loadedPluginRoot }) {
  const topo = await lib('antigravity-plugin-topology.mjs');
  return { governed: false, loaded: topo.observeAntigravityLoadedTopology({ loadedPluginRoot, configRoot, workspaceRoot }) };
}

