// Scratch-only mutation sanity check for B-S1-T2: copies the test + module (+ local imports) into a
// scratch work dir, applies one mutation to the COPY of the module, runs only the B-S1-T2 cases,
// and prints which cases went RED. The real module is never touched.
import { spawnSync } from "node:child_process";
import { copyFileSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const lib = join(here, "..", "plugins", "pipeline-core", "lib");
const work = join(here, "b-s1-t2-mut");

const mutations = [
  { id: "M0-baseline", find: null, replace: null },
  { id: "M1-no-exit-cleanup", find: 'process.on("exit", () => discard(root));', replace: "" },
  { id: "M2-no-discard-on-refusal", find: "    discard(root);\n    throw error;", replace: "    throw error;" },
  { id: "M3-no-repository-check", find: "if (repository !== null) {", replace: "if (false) {" },
  { id: "M4-no-invalid-prefix-check", find: 'if (typeof prefix !== "string" || prefix.length === 0) {', replace: "if (false) {" },
  { id: "M5-no-escape-check", find: 'if (rel === "" || rel.startsWith("..") || isAbsolute(rel)) {', replace: "if (false) {" },
];

function copyLocalClosure(name, seen = new Set()) {
  if (seen.has(name)) return seen;
  seen.add(name);
  copyFileSync(join(lib, name), join(work, name));
  const text = readFileSync(join(lib, name), "utf8");
  for (const match of text.matchAll(/from\s+"\.\/([^"]+\.mjs)"/g)) copyLocalClosure(match[1], seen);
  return seen;
}

const results = [];
try {
  for (const mutation of mutations) {
    rmSync(work, { recursive: true, force: true });
    mkdirSync(work, { recursive: true });
    copyLocalClosure("test-private-tmp.test.mjs");
    copyLocalClosure("test-private-tmp.mjs");
    if (mutation.find !== null) {
      const path = join(work, "test-private-tmp.mjs");
      const text = readFileSync(path, "utf8");
      if (!text.includes(mutation.find)) { results.push({ id: mutation.id, error: "mutation anchor not found" }); continue; }
      writeFileSync(path, text.replace(mutation.find, mutation.replace));
    }
    const run = spawnSync(process.execPath, ["--test", "--test-name-pattern=B-S1-T2", join(work, "test-private-tmp.test.mjs")], { encoding: "utf8", timeout: 240_000 });
    const lines = String(run.stdout).split(/\r?\n/).filter((line) => /^[✔✖]\s+B-S1-T2/u.test(line));
    results.push({
      id: mutation.id,
      exitStatus: run.status,
      red: lines.filter((line) => line.startsWith("✖")).map((line) => line.replace(/\s*\([\d.]+ms\)$/u, "")),
      green: lines.filter((line) => line.startsWith("✔")).length,
    });
  }
} finally {
  rmSync(work, { recursive: true, force: true });
}
console.log(JSON.stringify(results, null, 2));

