+          return envHasNoCommandOperand([...splitWords(value), ...args.slice(attached !== "" ? i + 1 : i + 2)]);
+        }
+        if (flag === "u" || flag === "C" || flag === "a") {
+          if (p === body.length - 1) consumed = 2;
+          break;
+        }
+      }
+      i += consumed;
+      continue;
+    }
