// SCRATCH ONLY (never committed): measures Q12-B + J on top of the unmodified module, with TWO candidate narrowings
// that the briefed literal rule does not contain:
//   N1: a backslash inside a well-formed quoted span (POSIX reading, via stripQuotedSegments) is data, not a marker.
//   N2: the "git word at an executable boundary" gate also sees `{` and `,` as boundaries and runs on the
//       brace-expanded forms of the text (so `g{i..i}t push` and `{git,push}` have a git word).
import * as real from "../../plugins/pipeline-core/lib/git-cmd.mjs";

export const { stripQuotedSegments, normalizeGlobalGitOptions, tokenizeArgv, refMatchesPattern } = real;

const GIT_BOUNDARY = /(?:^|[\s;&|(`'"/\\{,])git(?:\.exe)?\b/iu;
const NESTED_SHELL =
  /(?:^|[\s;&|(/\\])(?:(?:ba|z|da)?sh|pwsh|powershell)(?:\.exe)?\s+(?:-[A-Za-z]*c\b|-command\b)|(?:^|[\s;&|(/\\])cmd(?:\.exe)?\s+\/c\b|<<</iu;
const OTHER_MARKER = /[$`{()]|<<|[‘-‟‹›«»]/u;
const SEG = String.raw`[\w.~@%+=,#-]`;
const DRIVE_PATH = new RegExp(String.raw`^[A-Za-z]:\\(?:${SEG}+\\)*${SEG}*$`, "u");
const REL_PATH = new RegExp(String.raw`^${SEG}+(?:\\${SEG}+)+$`, "u");

function backslashIsMarker(cmd) {
  const outside = real.stripQuotedSegments(cmd); // N1
  if (!outside.includes("\\")) return false;
  for (const word of outside.split(/\s/u)) {
    if (!word.includes("\\")) continue;
    const bare = word.replace(/^["']+/u, "").replace(/["']+$/u, "");
    if (DRIVE_PATH.test(bare)) continue;
    if (REL_PATH.test(bare) && !/^(?:git(?:\.exe)?|push)$/iu.test(bare.replaceAll("\\", ""))) continue;
    return true;
  }
  return false;
}

// Minimal bash brace expansion for the gate (comma lists, single-char and integer sequences); null = cap exceeded.
function expandBraces(text, budget = { n: 256 }) {
  const open = text.indexOf("{");
  if (open === -1) return [text];
  let depth = 0;
  let close = -1;
  for (let i = open; i < text.length; i += 1) {
    if (text[i] === "{") depth += 1;
    else if (text[i] === "}" && --depth === 0) {
      close = i;
      break;
    }
  }
  if (close === -1) return [text];
  const body = text.slice(open + 1, close);
  const parts = [];
  let d = 0;
  let cur = "";
  for (const ch of body) {
    if (ch === "{") d += 1;
    if (ch === "}") d -= 1;
    if (ch === "," && d === 0) {
      parts.push(cur);
      cur = "";
    } else cur += ch;
  }
  parts.push(cur);
  let alts = null;
  if (parts.length > 1) alts = parts;
  else {
    const m = /^(\w)\.\.(\w)$/u.exec(body);
    if (m) {
      alts = [];
      const a = m[1].codePointAt(0);
      const b = m[2].codePointAt(0);
      for (let c = Math.min(a, b); c <= Math.max(a, b) && alts.length <= 64; c += 1) alts.push(String.fromCodePoint(c));
    }
  }
  const head = text.slice(0, open);
  const tail = text.slice(close + 1);
  if (alts === null) {
    const inner = expandBraces(tail, budget);
    return inner === null ? null : inner.map((t) => `${head}{${body}}${t}`);
  }
  const out = [];
  for (const alt of alts) {
    budget.n -= 1;
    if (budget.n < 0) return null;
    const expanded = expandBraces(`${head}${alt}${tail}`, budget);
    if (expanded === null) return null;
    out.push(...expanded);
  }
  return out;
}

function hasGitWord(cmd) {
  if (GIT_BOUNDARY.test(cmd)) return true;
  if (!cmd.includes("{")) return false;
  const expansions = expandBraces(cmd);
  return expansions === null || expansions.some((t) => GIT_BOUNDARY.test(t)); // N2
}

export function commandIsGitPush(cmd) {
  if (typeof cmd !== "string" || cmd === "") return false;
  if (hasGitWord(cmd) && (OTHER_MARKER.test(cmd) || NESTED_SHELL.test(cmd) || backslashIsMarker(cmd))) return true;
  return real.commandIsGitPush(cmd);
}

