  [String.raw`git -C <machine-path> -C <machine-path> push origin main`, "repeated -C drive paths, each ending in a backslash and a space"],
  [String.raw`& git -C <machine-path> push origin main`, "PowerShell call operator in front of git, then a drive path ending in a backslash"],
  [String.raw`cd <machine-path> ; git -C <machine-path> push origin main`, "a drive path ending in a backslash on a preceding command, then the push"],
  [String.raw`echo "x\"; git -c a=b -C <machine-path> push origin main; echo \"y"`, "the span-closing shape and the swallowing path together"],
