import { createHash, createPublicKey, verify } from "node:crypto";
import { appendFileSync, linkSync, lstatSync, mkdirSync, readdirSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createPoApprovalIntent, canonical } from "../../plugins/pipeline-core/lib/po-approval-proof.mjs";
const sha = (d) => createHash("sha256").update(Buffer.from(d)).digest("hex");
const D = sha("pipeline.legacy-custody-authorization.v1");
export function applyLegacyCustodyDisposition({ receiptsDirectory, sessionId, package: pkg, proof, anchor, archiveRoot }) {
  const refused = (code) => ({ status: "refused", code, mutated: false });
  const unavailable = (code) => ({ status: "unavailable", code, mutated: false });
  if (proof === null || typeof proof !== "object" || Array.isArray(proof) || typeof proof.signatureBase64 !== "string"
    || typeof proof.publicKey !== "string" || typeof proof.intentSha256 !== "string") return refused("LOC-PROOF-INVALID");
  const intent = createPoApprovalIntent({ kind: "legacy-custody", featureId: "legacy-custody", planSha256: D, specSha256: D,
    candidate: pkg.repository, policyRevision: "legacy-custody-v1", subjectSha256: sha(canonical(pkg)), decision: pkg.disposition });
  if (proof.intentSha256 !== intent.sha256) return refused("LOC-PROOF-BINDING-MISMATCH");
  if (sha(proof.publicKey) !== anchor.publicKeySha256) return refused("LOC-PROOF-SIGNER-MISMATCH");
  if (!verify(null, Buffer.from(intent.sha256, "utf8"), createPublicKey(proof.publicKey), Buffer.from(proof.signatureBase64, "base64"))) return refused("LOC-PROOF-INVALID");
  const names = readdirSync(receiptsDirectory).filter((n) => n === sessionId + ".json" || n.startsWith(sessionId + "."));
  if (names.length > 1) return unavailable("LOC-RECEIPT-AMBIGUOUS");
  if (pkg.receipt.absent === true) return names.length === 0 ? { status: "absence-bound", mutated: false } : unavailable("LOC-RECEIPT-AMBIGUOUS");
  if (names.length === 0) return unavailable("LOC-TARGET-UNSAFE");
  const path = join(receiptsDirectory, names[0]);
  if (lstatSync(path).isSymbolicLink()) return unavailable("LOC-TARGET-UNSAFE");
  const bytes = readFileSync(path);
  if (sha(bytes) !== pkg.receipt.sha256) return refused("LOC-PROOF-BINDING-MISMATCH");
  if (pkg.disposition === "preserve") return { status: "preserved", mutated: false };
  if (pkg.disposition === "replay") return unavailable("LOC-REPLAY-PRECONDITION");
  const target = join(archiveRoot, "archived", sessionId + "." + sha(bytes) + ".json");
  mkdirSync(join(archiveRoot, "archived"), { recursive: true });
  writeFileSync(target, bytes, { flag: "wx" });
  if (!readFileSync(target).equals(bytes)) throw new Error("readback");
  appendFileSync(join(archiveRoot, "legacy-custody-archive-audit.jsonl"), JSON.stringify({
    schema: "pipeline.legacy-custody-archive-audit.v1", sessionId, receiptSha256: sha(bytes), disposition: "archive", archivedAt: new Date().toISOString() }) + "\n");
  unlinkSync(path);
  return { status: "archived", mutated: true };
}

