// Builds the signed-quality-package intent for the tranche (decision BF): R7-6-P pipeline-state post-image, the ENVDUMP
// lane (new file) plus its evaluate.mjs call site, and the verify-suites registrations.
// Run from the repository root on a clean tree: node scratch/T1/build.mjs   (--dry skips the clean-tree check, preview only)
import { spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { createHash } from "node:crypto";
import { SIGNED_QUALITY_PACKAGE_SCHEMA, qualityPackageIntentSha256 } from "../../plugins/pipeline-core/lib/signed-quality-package.mjs";

const REPO = process.cwd();
const WORK = join(REPO, "scratch", "T1");
const POST = "specs/sprint-alfred-epic/signed-package/tranche-1";
const TARGETS = [
  "harness/verify-suites.json",
  "plugins/pipeline-core/lib/guard/env-dump-lane.mjs",
  "plugins/pipeline-core/lib/guard/evaluate.mjs",
  "plugins/pipeline-core/scripts/pipeline-state.mjs",
];
const DRY = process.argv.includes("--dry");

function run(cmd, args, opts = {}) {
  const r = spawnSync(cmd, args, { encoding: null, shell: false, windowsHide: true, maxBuffer: 256 * 1024 * 1024, input: "", ...opts });
  if (r.error) throw r.error;
  return r;
}
const sha = (buf) => createHash("sha256").update(buf).digest("hex");

const status = run("git", ["status", "--porcelain"], { cwd: REPO }).stdout.toString("utf8");
if (status !== "" && !DRY) { console.error(`T1: working tree not clea<machine-path>`); process.exit(1); }
const head = run("git", ["rev-parse", "HEAD"], { cwd: REPO }).stdout.toString("utf8").trim();

for (const side of ["a", "b"]) rmSync(join(WORK, side), { recursive: true, force: true });
let unifiedDiff = "";
const expectedDigests = {};
for (const path of TARGETS) {
  const blob = run("git", ["cat-file", "-e", `HEAD:${path}`], { cwd: REPO });
  const isNew = blob.status !== 0;
  // verify-suites.json is TP-13-protected even as a tracked copy, so its post-image lives in scratch/T1/post.
  const source = path === "harness/verify-suites.json" ? `scratch/T1/post/${path}` : `${POST}/${path}`;
  const post = readFileSync(join(REPO, ...source.split("/")));
  if (!isNew) {
    const base = run("git", ["show", `HEAD:${path}`], { cwd: REPO });
    const dst = join(WORK, "a", ...path.split("/"));
    mkdirSync(dirname(dst), { recursive: true });
    writeFileSync(dst, base.stdout);
  }
  const dstB = join(WORK, "b", ...path.split("/"));
  mkdirSync(dirname(dstB), { recursive: true });
  writeFileSync(dstB, post);
  const r = isNew
    ? run("git", ["diff", "--no-index", "--no-color", "--no-ext-diff", "--src-prefix=a/", "--dst-prefix=b/", "--", "/dev/null", path], { cwd: join(WORK, "b") })
    : run("git", ["diff", "--no-index", "--no-color", "--no-ext-diff", "--src-prefix=", "--dst-prefix=", `a/${path}`, `b/${path}`], { cwd: WORK });
  if (r.status !== 1) { console.error(`T1: git diff for ${path} exited ${r.status}: ${r.stderr.toString("utf8")}`); process.exit(1); }
  unifiedDiff += r.stdout.toString("utf8");
  expectedDigests[path] = sha(post);
}
const record = { schema: SIGNED_QUALITY_PACKAGE_SCHEMA, baseCommit: head, unifiedDiff, expectedDigests };
record.intentSha256 = qualityPackageIntentSha256(record);
const suffix = DRY ? "-dry" : "";
writeFileSync(join(WORK, `t1-intent${suffix}.json`), `${JSON.stringify(record, null, 2)}\n`);
if (!DRY) writeFileSync(join(WORK, "t1-request.json"), `${JSON.stringify({ intentSha256: record.intentSha256 }, null, 2)}\n`);
console.log(JSON.stringify({ dry: DRY, baseCommit: head, intentSha256: record.intentSha256, targets: TARGETS, diffBytes: Buffer.byteLength(unifiedDiff) }, null, 2));

