const MAP = {
  "deterministic-verification": ["test-private-tmp-tests", "fs-durability-tests"],
  "continuity-and-handover": ["scratch-retention-tests", "scratch-sweep-tests"],
  "critical-human-authorization": ["design-consistency-check-tests", "design-review-receipt-tests", "design-approval-binding-tests", "pipeline-state-push-anchor-tests"],
  "repair-guidance-cli": ["recovery-refusal-registry-tests", "attended-recovery-tests", "legacy-owner-custody-tests", "legacy-owner-custody-archive-tests"],
  "setup-and-runtime-projection": ["agy-central-snapshot-tests", "hardened-private-directory-install-tests"],
