+    let i = start;
+    let words = [];
+    let targets = [];
+    let word = null;
+    let skipNext = false;
+    let depth = 0;
+    const finishWord = () => {
+      if (word === null) return;
+      (skipNext ? targets : words).push(word);
+      skipNext = false;
+      word = null;
+    };
+    const finishCommand = () => {
+      finishWord();
+      if (words.length > 0 || targets.length > 0) commands.push({ words, targets });
+      words = [];
+      targets = [];
+      skipNext = false;
+    };
