// Data-only probe for T1-F2: strings are classified in-process, never executed.
import { constants } from "node:buffer";
import { envDumpRule } from "../plugins/pipeline-core/lib/guard/env-dump-lane.mjs";

function nested(levels, tail) {
  let command = tail;
  for (let level = 0; level < levels; level += 1) command = `env -S '${command.replace(/'/gu, "'\\''")}'`;
  return command;
}

// 1. Growth of the pinned T3 builder: measured for small levels, then extrapolated with the recurrence.
const real = [];
for (let level = 1; level <= 9; level += 1) real.push(nested(level, "printenv").length);
let len = 17n;
let quotes = 2n;
const modelled = [len];
for (let level = 2; level <= 40; level += 1) {
  len = 9n + len + 3n * quotes;
  quotes = 2n + 3n * quotes;
  modelled.push(len);
}
console.log(JSON.stringify({
  maxStringLength: constants.MAX_STRING_LENGTH,
  realLengthsLevels1to9: real,
  modelledLevels1to9: modelled.slice(0, 9).map(String),
  modelledLevel20: String(modelled[19]),
  modelledLevel40: String(modelled[39]),
  firstLevelOverMax: modelled.findIndex((value) => value > BigInt(constants.MAX_STRING_LENGTH)) + 1,
}));

// 2. The lane itself.
function time(label, build) {
  const command = build();
  const start = performance.now();
  const rule = envDumpRule(command, "Bash");
  console.log(JSON.stringify({ label, words: command.split(" ").length, rule, ms: Math.round(performance.now() - start) }));
}
