// THROWAWAY reference implementation used only to self-validate the U1-T test file (scratch, never committed).
import { createHash } from "node:crypto";
import { canonical } from "../../plugins/pipeline-core/lib/po-approval-proof.mjs";
import { TECHNICAL_SPEC_MARKER } from "../../plugins/pipeline-core/lib/po-gate-authority.mjs";

export const DESIGN_CONSISTENCY_CHECK_SCHEMA = "pipeline.design-consistency-check.v1";
export const DESIGN_CONSISTENCY_CODES = Object.freeze([
  "DCC-PATH-UNSAFE", "DCC-PATH-IGNORED", "DCC-PATH-UNTRACKED", "DCC-PATH-MODIFIED", "DCC-PRD-DIGEST-DRIFT",
  "DCC-SPEC-DIGEST-DRIFT", "DCC-PRD-MARKER-MISSING", "DCC-PRD-MARKER-DUPLICATE", "DCC-PRD-MARKER-STALE",
  "DCC-COMPANION-UNBOUND", "DCC-REGISTER-INVALID", "DCC-ID-DUPLICATE", "DCC-COUNT-MISMATCH",
  "DCC-REVIEW-RECEIPT-MISSING", "DCC-REVIEW-RECEIPT-BINDING", "DCC-REVIEW-ROUND-EXCEEDED", "DCC-REVIEW-DELTA-CHAIN",
]);
export class DesignConsistencyCheckError extends Error {
  constructor(message) { super(message); this.name = "DesignConsistencyCheckError"; this.code = "DCC-INPUT"; }
}
const fail = (message) => { throw new DesignConsistencyCheckError(message); };
const HEX = /^[0-9a-f]{64}$/u;
const ID = /^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+){1,7}$/u;
const sha = (value) => createHash("sha256").update(value).digest("hex");
const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const keysAre = (v, keys) => isObj(v) && JSON.stringify(Object.keys(v).sort()) === JSON.stringify([...keys].sort());
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const decoder = new TextDecoder();

function safePath(p) {
  return typeof p === "string" && p.length >= 1 && p.length <= 240 && p === p.trim() && !p.includes("\\") && !p.includes("\0")
    && !p.startsWith("/") && !/^[A-Za-z]:/u.test(p) && !p.endsWith("/") && !p.split("/").some((s) => s === "" || s === "." || s === "..");
}
const entryOf = (code, f = {}) => ({ code, path: null, ids: [], expected: null, observed: null, ...f });
function sortEntries(entries) {
  const idx = (c) => DESIGN_CONSISTENCY_CODES.indexOf(c);
  return [...entries].sort((a, b) => idx(a.code) - idx(b.code)
    || (a.path === b.path ? 0 : a.path === null ? -1 : b.path === null ? 1 : cmp(a.path, b.path))
    || cmp(a.ids.join(","), b.ids.join(",")));
}

export function parseTraceabilityIds(text) {
  const ids = [];
  let fenced = false;
  for (const line of text.split(/\r?\n/u)) {
    const t = line.trim();
    if (t.startsWith("```") || t.startsWith("~~~")) { fenced = !fenced; continue; }
    if (fenced || !t.startsWith("|")) continue;
    const rest = t.slice(1);
    const end = rest.indexOf("|");
    let cell = (end === -1 ? rest : rest.slice(0, end)).trim();
    if (cell.length >= 2 && cell.startsWith("`") && cell.endsWith("`")) cell = cell.slice(1, -1);
    if (cell.length <= 80 && ID.test(cell)) ids.push(cell);
  }
  return ids;
}

export function registerFromRequirementTraceability(value, mapPath) {
  if (value instanceof Error || (isObj(value) && typeof value.code === "string" && value.name === "RequirementTraceabilityError")) {
    return { mode: "invalid", mapPath, rtCode: value.code };
  }
  if (value.mode === "declared") return { mode: "declared", mapPath, ids: value.criteria.map((c) => c.id) };
  return { mode: "undeclared", mapPath };
}

export function currentDesignSources({ submission, prdBytes, specBytes, companions, pathStates }) {
  return {
    prd: { path: submission.planPath, sha256: sha(prdBytes) },
    spec: { path: submission.specPath, sha256: sha(specBytes) },
    companions: [...companions].sort(cmp).map((path) => ({ path, sha256: pathStates.find((s) => s.path === path)?.sha256 ?? null })),
  };
}

function unreviewedDelta(latest, current) {
  const flat = (s) => new Map([[s.prd.path, s.prd.sha256], [s.spec.path, s.spec.sha256], ...s.companions.map((c) => [c.path, c.sha256])]);
  const a = flat(latest.sources);
  const b = flat(current);
  const out = [];
  for (const path of new Set([...a.keys(), ...b.keys()])) {
    const reviewed = a.get(path) ?? null;
    const now = b.get(path) ?? null;
    if (reviewed !== now) out.push({ path, reviewedSha256: reviewed, currentSha256: now });
  }
  return out.sort((x, y) => cmp(x.path, y.path));
}

export function reviewChainInconsistencies({ featureId, receipts, currentSources }) {
  const out = [];
  if (receipts === null || receipts.length === 0) return [entryOf("DCC-REVIEW-RECEIPT-MISSING")];
  const stubs = receipts.filter((r) => Object.hasOwn(r, "refusal"));
  for (const stub of stubs) out.push(entryOf("DCC-REVIEW-RECEIPT-BINDING", { path: stub.path, observed: stub.refusal }));
  if (stubs.length > 0) return sortEntries(out);
  for (const r of receipts) {
    if (r.featureId !== featureId) out.push(entryOf("DCC-REVIEW-RECEIPT-BINDING", { path: r.path, expected: featureId, observed: r.featureId }));
  }
  if (receipts.length > 2) return sortEntries([...out, entryOf("DCC-REVIEW-ROUND-EXCEEDED", { observed: String(receipts.length) })]);
  const [first, second] = receipts;
  if (first.kind !== "initial") out.push(entryOf("DCC-REVIEW-DELTA-CHAIN", { path: first.path }));
  if (second) {
    if (second.kind !== "delta" || second.previousReceiptSha256 !== first.sha256 || second.previousReceiptPath !== first.path
      || second.sources.prd.path !== first.sources.prd.path || second.sources.spec.path !== first.sources.spec.path) {
      out.push(entryOf("DCC-REVIEW-DELTA-CHAIN", { path: second.path, expected: first.sha256, observed: second.previousReceiptSha256 }));
    }
    if (canonical(second.sources) === canonical(first.sources)) out.push(entryOf("DCC-REVIEW-DELTA-CHAIN"));
  }
  const latest = receipts[receipts.length - 1];
  if (canonical(latest.sources) !== canonical(currentSources) && latest.kind !== "delta") {
    out.push(entryOf("DCC-REVIEW-RECEIPT-BINDING", { path: latest.path, expected: sha(canonical(currentSources)), observed: sha(canonical(latest.sources)) }));
  }
  return sortEntries(out);
}

const SUMMARY_KEYS = ["path", "sha256", "featureId", "kind", "round", "previousReceiptPath", "previousReceiptSha256", "sources", "report", "verdict", "openFindingIds"];
function validate(input) {
  if (!keysAre(input, ["submission", "prdBytes", "specBytes", "companions", "traceability", "register", "pathStates", "reviewReceipts"])) fail("input keys");
  const { submission, prdBytes, specBytes, companions, traceability, register, pathStates, reviewReceipts } = input;
  if (!keysAre(submission, ["featureId", "planPath", "planSha256", "specPath", "specSha256"])) fail("submission");
  if (!(prdBytes instanceof Uint8Array) || !(specBytes instanceof Uint8Array)) fail("bytes");
  if (!Array.isArray(companions) || companions.length > 64 || companions.some((c) => typeof c !== "string")) fail("companions");
  if (new Set(companions).size !== companions.length) fail("duplicate companions");
  if (companions.includes(submission.planPath) || companions.includes(submission.specPath)) fail("companions overlap");
  if (!Array.isArray(pathStates)) fail("pathStates");
  if (reviewReceipts !== null && !Array.isArray(reviewReceipts)) fail("reviewReceipts");
  for (const s of pathStates) {
    if (!keysAre(s, ["path", "tracked", "modified", "ignored", "regular", "sha256"])) fail("pathState shape");
    if (s.tracked && s.ignored) fail("tracked and ignored");
  }
  const bound = new Set([submission.planPath, submission.specPath, ...companions]);
  for (const r of reviewReceipts ?? []) {
    if (isObj(r) && Object.hasOwn(r, "refusal")) {
      if (!keysAre(r, ["path", "refusal"])) fail("stub shape");
      bound.add(r.path);
      continue;
    }
    if (!keysAre(r, SUMMARY_KEYS)) fail("summary keys");
    const delta = r.kind === "delta";
    if (!(r.kind === "initial" || delta)) fail("kind");
    if (delta ? !(r.round === 2 && r.previousReceiptPath !== null && r.previousReceiptSha256 !== null)
      : !(r.round === 1 && r.previousReceiptPath === null && r.previousReceiptSha256 === null)) fail("summary invariants");
    bound.add(r.path);
    bound.add(r.report.path);
  }
  const statePaths = pathStates.map((s) => s.path);
  if (statePaths.length !== bound.size || new Set(statePaths).size !== statePaths.length || statePaths.some((p) => !bound.has(p))) fail("pathStates not exactly one per bound path");
  const stateOf = (p) => pathStates.find((s) => s.path === p);
  if (stateOf(submission.planPath).sha256 !== sha(prdBytes)) fail("prd digest");
  if (stateOf(submission.specPath).sha256 !== sha(specBytes)) fail("spec digest");
  if (traceability !== null) {
    if (!keysAre(traceability, ["path", "bytes"]) || !(traceability.bytes instanceof Uint8Array)) fail("traceability shape");
    const dir = submission.specPath.split("/").slice(0, -1).join("/");
    if (traceability.path !== `${dir}/traceability.md`) fail("traceability path");
    const st = stateOf(traceability.path);
    if (st && st.sha256 !== sha(traceability.bytes)) fail("traceability digest");
  }
  if (!isObj(register) || !["declared", "undeclared", "invalid"].includes(register.mode)) fail("register");
  if (register.mode !== "undeclared" && traceability === null) fail("traceability required");
  if (register.mode === "declared") {
    if (!Array.isArray(register.ids) || register.ids.length > 64 || register.ids.some((i) => typeof i !== "string" || !ID.test(i)) || new Set(register.ids).size !== register.ids.length) fail("register ids");
  }
  for (const r of reviewReceipts ?? []) {
    if (Object.hasOwn(r, "refusal")) continue;
    if (stateOf(r.path).sha256 !== r.sha256) fail("summary digest");
  }
  return { stateOf };
}

export function checkDesignConsistency(input) {
  if (!isObj(input)) fail("input not an object");
  const { stateOf } = validate(input);
  const { submission, prdBytes, specBytes, companions, traceability, register, reviewReceipts } = input;
  const entries = [];
  const sources = currentDesignSources({ submission, prdBytes, specBytes, companions, pathStates: input.pathStates });

  const bound = [submission.planPath, submission.specPath, ...companions];
  for (const r of reviewReceipts ?? []) {
    bound.push(r.path);
    if (!Object.hasOwn(r, "refusal")) bound.push(r.report.path);
  }
  for (const p of bound) {
    const s = stateOf(p);
    if (!safePath(p) || !s.regular) entries.push(entryOf("DCC-PATH-UNSAFE", { path: p }));
    else if (s.ignored) entries.push(entryOf("DCC-PATH-IGNORED", { path: p }));
    else if (!s.tracked) entries.push(entryOf("DCC-PATH-UNTRACKED", { path: p }));
    else if (s.modified) entries.push(entryOf("DCC-PATH-MODIFIED", { path: p }));
  }
  if (sha(prdBytes) !== submission.planSha256) entries.push(entryOf("DCC-PRD-DIGEST-DRIFT", { path: submission.planPath, expected: submission.planSha256, observed: sha(prdBytes) }));
  if (sha(specBytes) !== submission.specSha256) entries.push(entryOf("DCC-SPEC-DIGEST-DRIFT", { path: submission.specPath, expected: submission.specSha256, observed: sha(specBytes) }));
  const matches = [...decoder.decode(prdBytes).matchAll(TECHNICAL_SPEC_MARKER)].map((m) => m[1]);
  if (matches.length === 0) entries.push(entryOf("DCC-PRD-MARKER-MISSING", { path: submission.planPath }));
  else if (matches.length > 1) entries.push(entryOf("DCC-PRD-MARKER-DUPLICATE", { path: submission.planPath, observed: String(matches.length) }));
  else if (matches[0] !== sha(specBytes)) entries.push(entryOf("DCC-PRD-MARKER-STALE", { path: submission.planPath, expected: sha(specBytes), observed: matches[0] }));

  if (traceability !== null && !companions.includes(traceability.path)) entries.push(entryOf("DCC-COMPANION-UNBOUND", { path: traceability.path }));
  if (register.mode !== "undeclared" && !companions.includes(register.mapPath)) entries.push(entryOf("DCC-COMPANION-UNBOUND", { path: register.mapPath }));

  let registerCount = null;
  let traceabilityCount = null;
  if (register.mode === "invalid") {
    entries.push(entryOf("DCC-REGISTER-INVALID", { path: register.mapPath, observed: register.rtCode }));
  } else if (register.mode === "declared") {
    const t = parseTraceabilityIds(decoder.decode(traceability.bytes));
    registerCount = register.ids.length;
    traceabilityCount = t.length;
    const dup = [...new Set(t.filter((id, i) => t.indexOf(id) !== i))].sort(cmp);
    if (dup.length > 0) entries.push(entryOf("DCC-ID-DUPLICATE", { path: traceability.path, ids: dup }));
    const tset = new Set(t);
    const rset = new Set(register.ids);
    const missing = register.ids.filter((id) => !tset.has(id)).sort(cmp);
    const extra = [...tset].filter((id) => !rset.has(id)).sort(cmp);
    if (missing.length > 0) entries.push(entryOf("DCC-COUNT-MISMATCH", { path: traceability.path, ids: missing }));
    if (extra.length > 0) entries.push(entryOf("DCC-COUNT-MISMATCH", { path: register.mapPath, ids: extra }));
  }

  const reviewEntries = reviewChainInconsistencies({ featureId: submission.featureId, receipts: reviewReceipts, currentSources: sources });
  for (const r of reviewReceipts ?? []) {
    if (Object.hasOwn(r, "refusal")) continue;
    const st = stateOf(r.report.path);
    if (st.sha256 !== r.report.sha256) reviewEntries.push(entryOf("DCC-REVIEW-RECEIPT-BINDING", { path: r.report.path, expected: r.report.sha256, observed: st.sha256 }));
  }
  entries.push(...reviewEntries);

  let review = null;
  if (reviewEntries.length === 0) {
    const latest = reviewReceipts[reviewReceipts.length - 1];
    review = {
      rounds: reviewReceipts.length,
      latestReceiptSha256: latest.sha256,
      verdict: latest.verdict,
      openFindingIds: latest.openFindingIds,
      unreviewedSourceDelta: latest.kind === "delta" ? unreviewedDelta(latest, sources) : [],
    };
  }
  const sorted = sortEntries(entries);
  return {
    schema: DESIGN_CONSISTENCY_CHECK_SCHEMA,
    ok: sorted.length === 0,
    featureId: submission.featureId,
    sources,
    register: { mode: register.mode, mapPath: register.mapPath, registerCount, traceabilityCount },
    review,
    inconsistencies: sorted,
  };
}

