// Scratch reference reading of the U2 contract, used ONLY to check that the RED test file is self-consistent. Not the module.
import { createHash } from "node:crypto";
import { canonical } from "./po-approval-proof.mjs";

export const DESIGN_REVIEW_RECEIPT_SCHEMA = "pipeline.design-review-receipt.v1";
export const DESIGN_REVIEW_MAX_ROUNDS = 2;
export const DESIGN_REVIEW_RECEIPT_MAX_BYTES = 65536;

const SHA = /^[a-f0-9]{64}$/u;
const FEATURE = /^[a-z][a-z0-9-]{0,63}$/u;
const RUNNER = /^[a-z][a-z0-9-]{0,63}$/u;
const MODEL = /^[A-Za-z0-9][A-Za-z0-9._:[\]-]{0,127}$/u;
const ID = /^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+){1,7}$/u;
const KEYS = ["schema", "featureId", "kind", "round", "previousReceiptPath", "previousReceiptSha256", "sources", "reviewer", "report", "verdict", "openFindingIds", "reviewedAt"];
const sha = (value) => createHash("sha256").update(value).digest("hex");
const refuse = (code) => ({ ok: false, code });
const closed = (v, keys) => v !== null && typeof v === "object" && !Array.isArray(v) && Object.keys(v).length === keys.length && keys.every((k) => Object.hasOwn(v, k));
const str = (v) => typeof v === "string";
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const safePath = (p) => str(p) && p.length >= 1 && p.length <= 240 && p === p.trim() && !p.includes("\\") && !p.includes("\0") && !p.startsWith("/") && !/^[A-Za-z]:/u.test(p) && !p.endsWith("/") && p.split("/").every((s) => s !== "" && s !== "." && s !== "..");
const fileRef = (v) => closed(v, ["path", "sha256"]) && str(v.path) && str(v.sha256) && SHA.test(v.sha256);

function iso(x) { if (!str(x)) return false; try { return new Date(x).toISOString() === x; } catch { return false; } }

function shapeOk(r) {
  if (!closed(r, KEYS) || r.schema !== DESIGN_REVIEW_RECEIPT_SCHEMA) return false;
  if (!str(r.featureId) || !FEATURE.test(r.featureId) || !["initial", "delta"].includes(r.kind) || !Number.isInteger(r.round) || r.round < 1) return false;
  if (!(r.previousReceiptPath === null || str(r.previousReceiptPath)) || !(r.previousReceiptSha256 === null || (str(r.previousReceiptSha256) && SHA.test(r.previousReceiptSha256)))) return false;
  const s = r.sources;
  if (!closed(s, ["prd", "spec", "companions"]) || !fileRef(s.prd) || !fileRef(s.spec) || !Array.isArray(s.companions) || !s.companions.every(fileRef)) return false;
  if (!closed(r.reviewer, ["runner", "model"]) || !str(r.reviewer.runner) || !RUNNER.test(r.reviewer.runner) || !str(r.reviewer.model) || !MODEL.test(r.reviewer.model)) return false;
  if (!fileRef(r.report) || !["pass", "open-findings"].includes(r.verdict) || !Array.isArray(r.openFindingIds) || !r.openFindingIds.every(str) || !iso(r.reviewedAt)) return false;
  return true;
}

function validate(r) {
  if (!shapeOk(r)) return "DRR-SHAPE";
  const s = r.sources;
  const bound = [s.prd.path, s.spec.path, ...s.companions.map((c) => c.path), r.report.path];
  if (r.previousReceiptPath !== null) bound.push(r.previousReceiptPath);
  if (!bound.every(safePath)) return "DRR-PATH";
  const others = [s.prd.path, s.spec.path, ...s.companions.map((c) => c.path)];
  if (r.previousReceiptPath !== null) others.push(r.previousReceiptPath);
  if (others.includes(r.report.path)) return "DRR-PATH";
  const paths = s.companions.map((c) => c.path);
  if (s.companions.length > 64 || paths.some((p, i) => i > 0 && cmp(paths[i - 1], p) >= 0) || paths.includes(s.prd.path) || paths.includes(s.spec.path) || s.prd.path === s.spec.path) return "DRR-SOURCES";
  const ids = r.openFindingIds;
  if (ids.length > 64 || ids.some((id, i) => !ID.test(id) || id.length > 80 || (i > 0 && cmp(ids[i - 1], id) >= 0))) return "DRR-FINDING-IDS";
  if ((r.verdict === "pass") !== (ids.length === 0)) return "DRR-VERDICT";
  if (r.round > DESIGN_REVIEW_MAX_ROUNDS) return "DRR-ROUND-EXCEEDED";
  const hasPrev = r.previousReceiptPath !== null && r.previousReceiptSha256 !== null;
  const noPrev = r.previousReceiptPath === null && r.previousReceiptSha256 === null;
  if (r.kind === "initial" ? !(r.round === 1 && noPrev) : !(r.round === 2 && hasPrev)) return "DRR-KIND-ROUND";
  return null;
}

export function parseDesignReviewReceipt(bytes) {
  const buf = Buffer.from(bytes);
  if (buf.length === 0 || buf.length > DESIGN_REVIEW_RECEIPT_MAX_BYTES) return refuse("DRR-SIZE");
  let value;
  try { value = JSON.parse(buf.toString("utf8")); } catch { return refuse("DRR-JSON"); }
  if (!buf.equals(Buffer.from(`${canonical(value)}\n`, "utf8"))) return refuse("DRR-NONCANONICAL");
  const code = validate(value);
  return code ? refuse(code) : { ok: true, receipt: value, sha256: sha(buf) };
}

export function createDesignReviewReceipt({ featureId, previous, sources, reviewer, report, openFindingIds, reviewedAt }) {
  const sorted = sources && typeof sources === "object" && Array.isArray(sources.companions) ? { ...sources, companions: [...sources.companions].sort((a, b) => cmp(a?.path, b?.path)) } : sources;
  const ids = Array.isArray(openFindingIds) ? [...openFindingIds].sort(cmp) : openFindingIds;
  const receipt = {
    schema: DESIGN_REVIEW_RECEIPT_SCHEMA, featureId, kind: previous === null ? "initial" : "delta", round: previous === null ? 1 : 2,
    previousReceiptPath: previous === null ? null : previous.path, previousReceiptSha256: previous === null ? null : sha(Buffer.from(previous.bytes)),
    sources: sorted, reviewer, report, verdict: Array.isArray(ids) && ids.length === 0 ? "pass" : "open-findings", openFindingIds: ids, reviewedAt,
  };
  const code = validate(receipt);
  if (code) return refuse(code);
  if (previous !== null) {
    const prev = parseDesignReviewReceipt(previous.bytes);
    if (!prev.ok) return refuse("DRR-DELTA-CHAIN");
    if (prev.receipt.round >= DESIGN_REVIEW_MAX_ROUNDS) return refuse("DRR-ROUND-EXCEEDED");
    if (prev.receipt.featureId !== featureId || prev.receipt.sources.prd.path !== sources.prd.path || prev.receipt.sources.spec.path !== sources.spec.path) return refuse("DRR-DELTA-CHAIN");
    if (canonical(prev.receipt.sources) === canonical(receipt.sources)) return refuse("DRR-DELTA-UNCHANGED");
  }
  const bytes = Buffer.from(`${canonical(receipt)}\n`, "utf8");
  return { ok: true, receipt, bytes, sha256: sha(bytes) };
}

export function summarizeDesignReviewReceipt({ path, bytes }) {
  const parsed = parseDesignReviewReceipt(bytes);
  if (!parsed.ok) return refuse(parsed.code);
  const { schema, reviewer, reviewedAt, ...rest } = parsed.receipt;
  void schema; void reviewer; void reviewedAt;
  return { ok: true, summary: { path, sha256: parsed.sha256, ...rest } };
}

export function checkDesignReviewReceiptSources({ summary, currentSources }) {
  if (canonical(summary.sources) === canonical(currentSources)) return { ok: true };
  return { ok: false, code: "DRR-SOURCE-DRIFT", nextRound: summary.kind === "initial" ? 2 : null };
}

