// Throwaway prototype used only to prove the U3 RED test is satisfiable. Never committed.
import { createHash } from "node:crypto";
import { reviewChainInconsistencies } from "./design-consistency-check.mjs";
import { summarizeDesignReviewReceipt } from "./design-review-receipt.mjs";
import { canonical, createPoApprovalIntent } from "./po-approval-proof.mjs";

export const DESIGN_APPROVAL_BINDING_SCHEMA = "pipeline.design-approval-binding.v1";
export const DESIGN_APPROVAL_REQUEST_SCHEMA = "pipeline.design-approval-request.v1";
export const DESIGN_APPROVAL_RECORD_SCHEMA = "pipeline.design-approval.v1";
export const DESIGN_APPROVAL_INTENT_KIND = "design-approval";
export const DESIGN_APPROVAL_POLICY_REVISION = "design-approval-v1";

const SHA = /^[a-f0-9]{64}$/u;
const FEATURE = /^[a-z][a-z0-9-]{0,63}$/u;
const ID = /^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+){1,7}$/u;
const sha256 = (text) => createHash("sha256").update(text).digest("hex");
const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const exact = (v, keys) => isObj(v) && Object.keys(v).length === keys.length && keys.every((k) => Object.hasOwn(v, k));
const isSha = (v) => typeof v === "string" && SHA.test(v);
const refuse = (code, causes = []) => ({ ok: false, code, causes: [...causes].sort() });
const sourcesOk = (s) => exact(s, ["prd", "spec", "companions"])
  && exact(s.prd, ["path", "sha256"]) && typeof s.prd.path === "string" && isSha(s.prd.sha256)
  && exact(s.spec, ["path", "sha256"]) && typeof s.spec.path === "string" && isSha(s.spec.sha256)
  && Array.isArray(s.companions)
  && s.companions.every((c, i) => exact(c, ["path", "sha256"]) && typeof c.path === "string" && isSha(c.sha256) && (i === 0 || s.companions[i - 1].path < c.path));

export function validateDesignApprovalBinding(b) {
  const shape = refuse("DAB-SHAPE");
  if (!isObj(b)) return shape;
  const keys = ["schema", "featureId", "sources", "reviewReceipts", "verdict", "openFindingIds"];
  const hasDelta = Object.hasOwn(b, "unreviewedSourceDelta");
  if (hasDelta) keys.push("unreviewedSourceDelta");
  if (!exact(b, keys) || b.schema !== DESIGN_APPROVAL_BINDING_SCHEMA) return shape;
  if (typeof b.featureId !== "string" || !FEATURE.test(b.featureId) || !sourcesOk(b.sources)) return shape;
  const rr = b.reviewReceipts;
  if (!Array.isArray(rr) || rr.length < 1 || rr.length > 2) return shape;
  if (!rr.every((r, i) => exact(r, ["path", "sha256", "round"]) && typeof r.path === "string" && isSha(r.sha256) && r.round === i + 1)) return shape;
  if (b.verdict !== "pass" && b.verdict !== "open-findings") return shape;
  if (!Array.isArray(b.openFindingIds) || !b.openFindingIds.every((id) => typeof id === "string" && ID.test(id))) return shape;
  if (hasDelta) {
    const d = b.unreviewedSourceDelta;
    if (rr.length !== 2 || !Array.isArray(d) || d.length === 0) return shape;
    if (!d.every((e, i) => exact(e, ["path", "reviewedSha256", "currentSha256"]) && typeof e.path === "string" && isSha(e.reviewedSha256) && isSha(e.currentSha256) && (i === 0 || d[i - 1].path < e.path))) return shape;
  }
  return { ok: true, bindingSha256: sha256(canonical(b)) };
}

function deltaOf(reviewed, current) {
  const flat = (s) => new Map([[s.prd.path, s.prd.sha256], [s.spec.path, s.spec.sha256], ...s.companions.map((c) => [c.path, c.sha256])]);
  const a = flat(reviewed);
  const c = flat(current);
  const out = [];
  for (const path of [...new Set([...a.keys(), ...c.keys()])].sort()) {
    if (a.get(path) === c.get(path)) continue;
    out.push({ path, reviewedSha256: a.get(path) ?? null, currentSha256: c.get(path) ?? null });
  }
  return out;
}

export function createDesignApprovalBinding({ featureId, receipts, currentSources }) {
  const summaries = [];
  const drr = [];
  for (const r of receipts) {
    const s = summarizeDesignReviewReceipt(r);
    if (s.ok) summaries.push(s.summary);
    else drr.push(s.code);
  }
  if (drr.length > 0) return refuse("DAB-RECEIPT", new Set(drr));
  const entries = reviewChainInconsistencies({ featureId, receipts: summaries, currentSources });
  if (entries.length > 0) return refuse("DAB-REVIEW-CHAIN", new Set(entries.map((e) => e.code)));
  const latest = summaries[summaries.length - 1];
  const binding = {
    schema: DESIGN_APPROVAL_BINDING_SCHEMA,
    featureId,
    sources: structuredClone(currentSources),
    reviewReceipts: summaries.map((s) => ({ path: s.path, sha256: s.sha256, round: s.round })),
    verdict: latest.verdict,
    openFindingIds: [...latest.openFindingIds],
  };
  if (latest.kind === "delta") {
    const delta = deltaOf(latest.sources, currentSources);
    if (delta.length > 0) binding.unreviewedSourceDelta = delta;
  }
  const checked = validateDesignApprovalBinding(binding);
  if (!checked.ok) return refuse("DAB-SHAPE");
  return { ok: true, binding, bindingSha256: checked.bindingSha256 };
}

function intentFor(binding, bindingSha256, candidate) {
  return createPoApprovalIntent({
    kind: DESIGN_APPROVAL_INTENT_KIND,
    featureId: binding.featureId,
    planSha256: binding.sources.prd.sha256,
    specSha256: binding.sources.spec.sha256,
    candidate,
    policyRevision: DESIGN_APPROVAL_POLICY_REVISION,
    subjectSha256: bindingSha256,
    decision: "approve",
  });
}

export function createDesignApprovalRequest({ binding, candidate }) {
  const checked = validateDesignApprovalBinding(binding);
  if (!checked.ok) return checked;
  let intent;
  try {
    intent = intentFor(binding, checked.bindingSha256, candidate);
  } catch {
    return refuse("DAB-INTENT");
  }
  return {
    ok: true,
    request: {
      schema: DESIGN_APPROVAL_REQUEST_SCHEMA,
      binding: structuredClone(binding),
      bindingSha256: checked.bindingSha256,
      approvalIntent: { value: intent.value, sha256: intent.sha256 },
    },
    intentSha256: intent.sha256,
  };
}

export function classifyDesignApprovalIntent(intent) {
  const v = isObj(intent) && isObj(intent.value) ? intent.value : intent;
  if (!isObj(v)) return "unknown";
  if (v.kind === "design-workflow-package" && (v.policyRevision === "design-workflow-package-v1" || v.policyRevision === "design-workflow-package-v2")) return "legacy-design-workflow-package";
  if (v.kind === DESIGN_APPROVAL_INTENT_KIND && v.policyRevision === DESIGN_APPROVAL_POLICY_REVISION && v.schema === "pipeline.po-approval-intent.v1") return "design-approval";
  return "unknown";
}

export function classifyDesignApprovalRecord(record) {
  if (!isObj(record)) return "unknown";
  if (record.schema === DESIGN_APPROVAL_RECORD_SCHEMA) return Object.hasOwn(record, "packageSha256") || Object.hasOwn(record, "advisorException") ? "invalid" : "design-approval";
  if (record.schema === "pipeline.design-workflow-package-approval.v1") return "legacy-design-workflow-package";
  return "unknown";
}

export function verifyDesignApprovalRequest({ request, featureId, receipts, currentSources }) {
  if (!exact(request, ["schema", "binding", "bindingSha256", "approvalIntent"]) || request.schema !== DESIGN_APPROVAL_REQUEST_SCHEMA
    || !isSha(request.bindingSha256) || !exact(request.approvalIntent, ["value", "sha256"]) || !isSha(request.approvalIntent.sha256)) return refuse("DAB-SHAPE");
  if (!validateDesignApprovalBinding(request.binding).ok) return refuse("DAB-SHAPE");
  const kind = classifyDesignApprovalIntent(request.approvalIntent.value);
  if (kind === "legacy-design-workflow-package") return refuse("DAB-LEGACY-KIND", ["DWP2-LEGACY-APPROVED-REREAD"]);
  if (kind === "unknown") return refuse("DAB-KIND");
  if (request.binding.featureId !== featureId) return refuse("DAB-REVIEW-CHAIN", ["DCC-REVIEW-RECEIPT-BINDING"]);
  const recomputed = createDesignApprovalBinding({ featureId, receipts, currentSources });
  if (!recomputed.ok) return recomputed;
  if (canonical(request.binding) !== canonical(recomputed.binding) || request.bindingSha256 !== recomputed.bindingSha256) return refuse("DAB-BINDING-DRIFT");
  const candidate = request.approvalIntent.value.candidate;
  let expected;
  try {
    expected = intentFor(request.binding, recomputed.bindingSha256, candidate);
  } catch {
    return refuse("DAB-INTENT");
  }
  if (expected.sha256 !== request.approvalIntent.sha256 || canonical(expected.value) !== canonical(request.approvalIntent.value)) return refuse("DAB-INTENT-DRIFT");
  return {
    ok: true,
    bindingSha256: recomputed.bindingSha256,
    intentSha256: expected.sha256,
    candidate: structuredClone(candidate),
    verdict: request.binding.verdict,
    openFindingIds: [...request.binding.openFindingIds],
  };
}

