// Throwaway runner: assembles scratch/u3-proto-run (re-export stubs of the real U1/U2/proof modules,
// the prototype and a copy of the committed-to-be test) and runs the copy. Never committed.
import { spawnSync } from "node:child_process";
import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const root = resolve(import.meta.dirname, "..", "..");
const lib = resolve(root, "plugins", "pipeline-core", "lib");
const out = resolve(root, "scratch", "u3-proto-run");
mkdirSync(out, { recursive: true });
for (const name of ["design-consistency-check", "design-review-receipt", "po-approval-proof"]) {
  writeFileSync(resolve(out, `${name}.mjs`), `export * from ${JSON.stringify(pathToFileURL(resolve(lib, `${name}.mjs`)).href)};\n`);
}
copyFileSync(resolve(import.meta.dirname, "design-approval-binding.mjs"), resolve(out, "design-approval-binding.mjs"));
copyFileSync(resolve(lib, "design-approval-binding.test.mjs"), resolve(out, "design-approval-binding.test.mjs"));
const run = spawnSync(process.execPath, ["--test", resolve(out, "design-approval-binding.test.mjs")], { encoding: "utf8" });
process.stdout.write(run.stdout);
process.stderr.write(run.stderr);
process.exit(run.status ?? 1);
